ALTER TABLE Projects ADD COLUMN PublishedProjectVersionId VARCHAR(100) NULL;
CREATE TABLE IF NOT EXISTS ProjectPublications(Id VARCHAR(100) PRIMARY KEY, ProjectId VARCHAR(100) NOT NULL, GraphVersionId VARCHAR(100) NOT NULL, ManifestKey VARCHAR(255) NOT NULL, CreatedAt VARCHAR(40) NOT NULL, INDEX(ProjectId));
CREATE TABLE IF NOT EXISTS ProjectSceneVersions(ProjectVersionId VARCHAR(100) NOT NULL, SceneId VARCHAR(100) NOT NULL, SceneVersionId VARCHAR(100) NOT NULL, PRIMARY KEY(ProjectVersionId,SceneId), INDEX(SceneVersionId));
